def compute_model_placement(gpu_num, models):
    """
    Compute a model placement that minimizes the maximum KVPR across all GPUs.

    Args:
        gpu_num: Number of GPUs
        models: List of models to place

    Returns:
        A placement of models to GPUs
    """

    # Greedy placement: for each model, choose the GPU where the resulting
    # KVPR (after adding the model) is smallest, among GPUs that fit it.
    # Try several model orderings (deterministic heuristics plus randomized
    # perturbations within a time budget), refine each with a
    # move/swap local search, and keep the best feasible placement.

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free_mem = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num  # sum of req_rate/slo per GPU
        for m in order:
            best, best_kvpr = None, float('inf')
            for g in range(gpu_num):
                rem = free_mem[g] - m.model_size
                if rem <= 0:
                    continue
                kvpr = (load[g] + m.req_rate / m.slo) / rem
                if kvpr < best_kvpr:
                    best_kvpr, best = kvpr, g
            if best is None:
                return None
            placement[best].append(m)
            load[best] += m.req_rate / m.slo
            free_mem[best] -= m.model_size
        return placement

    def max_kvpr(placement):
        worst = 0.0
        for g, ms in placement.items():
            if not ms:
                continue
            load = sum(m.req_rate / m.slo for m in ms)
            free = GPU_MEM_SIZE - sum(m.model_size for m in ms)
            if free <= 0:
                return float('inf')
            worst = max(worst, load / free)
        return worst

    def local_search(placement):
        # Repeatedly move a single model to another GPU, or swap a pair of
        # models between two GPUs, whenever it lowers the max KVPR.
        # Plateau moves (max unchanged but lower sum of squared KVPRs) are
        # also accepted so the search can drift past flat local optima.
        def gpu_kvpr(g, skip=None, add=None, rem_size=0.0, add_load=0.0):
            size = GPU_MEM_SIZE - rem_size
            load = 0.0
            for x in placement[g]:
                if x is skip:
                    continue
                size -= x.model_size
                load += x.req_rate / x.slo
            for x in (add or []):
                size -= x.model_size
                load += x.req_rate / x.slo
            if size <= 0:
                return float('inf')
            return (load + add_load) / size

        def overall(kvprs):
            return max(kvprs) if kvprs else 0.0

        kvprs = [gpu_kvpr(g) for g in range(gpu_num)]
        worst = overall(kvprs)
        improved = True
        while improved:
            improved = False
            # Try single-model moves: evaluate via cached per-GPU KVPRs
            for src in range(gpu_num):
                if not placement[src]:
                    continue
                for m in list(placement[src]):
                    m_load = m.req_rate / m.slo
                    src_new = (kvprs[src] * (GPU_MEM_SIZE - sum(x.model_size for x in placement[src])) - m_load) / (GPU_MEM_SIZE - sum(x.model_size for x in placement[src]) + m.model_size) if kvprs[src] != float('inf') else gpu_kvpr(src, skip=m)
                    for dst in range(gpu_num):
                        if dst == src:
                            continue
                        dst_free = GPU_MEM_SIZE - sum(x.model_size for x in placement[dst])
                        if dst_free - m.model_size <= 0:
                            continue
                        dst_new = (kvprs[dst] * dst_free + m_load) / (dst_free - m.model_size) if kvprs[dst] != float('inf') else gpu_kvpr(dst, add=[m])
                        cand = max(src_new, dst_new)
                        for g in range(gpu_num):
                            if g != src and g != dst and kvprs[g] > cand:
                                cand = kvprs[g]
                        if cand < worst - 1e-12 or (cand < worst + 1e-12 and src_new < kvprs[src] - 1e-12 and dst_new < kvprs[src] - 1e-12):
                            placement[src].remove(m)
                            placement[dst].append(m)
                            kvprs[src] = gpu_kvpr(src)
                            kvprs[dst] = gpu_kvpr(dst)
                            worst = overall(kvprs)
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                continue
            # Try pairwise swaps between GPUs
            for a in range(gpu_num):
                for b in range(a + 1, gpu_num):
                    if not placement[a] or not placement[b]:
                        continue
                    done = False
                    for ma in list(placement[a]):
                        for mb in list(placement[b]):
                            a_new = gpu_kvpr(a, skip=ma, add=[mb])
                            b_new = gpu_kvpr(b, skip=mb, add=[ma])
                            cand = max(a_new, b_new)
                            for g in range(gpu_num):
                                if g != a and g != b and kvprs[g] > cand:
                                    cand = kvprs[g]
                            if cand < worst - 1e-12 or (cand < worst + 1e-12 and a_new < kvprs[a] - 1e-12 and b_new < kvprs[a] - 1e-12):
                                placement[a].remove(ma)
                                placement[b].remove(mb)
                                placement[a].append(mb)
                                placement[b].append(ma)
                                kvprs[a] = a_new
                                kvprs[b] = b_new
                                worst = overall(kvprs)
                                improved = True
                                done = True
                                break
                        if done:
                            break
                    if improved:
                        break
                if improved:
                    break
        return placement

    import time, random

    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo),
        sorted(models, key=lambda m: m.model_size),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / max(m.model_size, 1e-9), reverse=True),
        list(models),
    ]

    best_result, best_score = None, float('inf')
    for order in orders:
        result = greedy(order)
        if result is None:
            continue
        result = local_search(result)
        score = max_kvpr(result)
        if score < best_score:
            best_score, best_result = score, result

    # Simulated annealing over the best placement found so far:
    # random move/swap proposals accepted with a decaying temperature,
    # escaping local optima that greedy restarts cannot.
    deadline = time.time() + 2.5
    rng = random.Random(0)
    if best_result is not None:
        cur = {g: list(ms) for g, ms in best_result.items()}
        cur_score = best_score
        T0 = max(cur_score, 1e-9)
        t_start = time.time()
        while time.time() < deadline and best_score > 1e-9:
            frac = (time.time() - t_start) / 2.5
            T = T0 * (1.0 - frac) * 0.05 + 1e-12
            # propose a random move or swap
            if rng.random() < 0.5:
                src = rng.randrange(gpu_num)
                if not cur[src]:
                    continue
                dst = rng.randrange(gpu_num)
                if dst == src:
                    continue
                idx = rng.randrange(len(cur[src]))
                m = cur[src][idx]
                if GPU_MEM_SIZE - sum(x.model_size for x in cur[dst]) - m.model_size <= 0:
                    continue
                cur[src].pop(idx)
                cur[dst].append(m)
                s = max_kvpr(cur)
                if s < cur_score or rng.random() < pow(2.718281828, -(s - cur_score) / T):
                    cur_score = s
                    if s < best_score:
                        best_score = s
                        best_result = {g: list(ms) for g, ms in cur.items()}
                else:
                    cur[dst].remove(m)
                    cur[src].append(m)
            else:
                a = rng.randrange(gpu_num)
                b = rng.randrange(gpu_num)
                if a == b or not cur[a] or not cur[b]:
                    continue
                ia = rng.randrange(len(cur[a]))
                ib = rng.randrange(len(cur[b]))
                cur[a][ia], cur[b][ib] = cur[b][ib], cur[a][ia]
                s = max_kvpr(cur)
                if s < cur_score or rng.random() < pow(2.718281828, -(s - cur_score) / T):
                    cur_score = s
                    if s < best_score:
                        best_score = s
                        best_result = {g: list(ms) for g, ms in cur.items()}
                else:
                    cur[a][ia], cur[b][ib] = cur[b][ib], cur[a][ia]

    if best_result is None:
        raise ValueError("Unable to place all models within GPU memory.")

    return best_result

